import{z as i,x as l,o as E,c as d,q as r,j as B,D as e,d as s,s as A,S as o}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"步长与流预取器","description":"","frontmatter":{"title":"步长与流预取器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/stride-stream-prefetch.md","filePath":"cs/stride-stream-prefetch.md","lastUpdated":1791063341000}'),n={name:"cs/stride-stream-prefetch.md"};function p(C,a,c,m,D,h){const t=l("Mermaid");return E(),d("div",null,[a[2]||(a[2]=r('<h1 id="步长与流预取器" tabindex="-1">步长与流预取器 <a class="header-anchor" href="#步长与流预取器" aria-label="Permalink to &quot;步长与流预取器&quot;">​</a></h1><div class="epigraph"><p>连续缺失若地址相差固定块距，就按该距向前发；流缓冲把预取与 L1 隔开，避免直接映射被未来块踢伤当前行。</p><footer>—— 据 Jouppi, ISCA 1990；Baer and Chen, An Effective On-Chip Preloading Scheme, ISCA 1991 整理</footer></div><p><a href="/cs/mlp-memory-parallelism">上一课</a> 要飞行中的请求。<a href="/cs/cache-prefetch">主干预取课</a> 已给出直觉。本课在进阶课序里把<strong>步长预测与流预取器</strong>写具体：如何检出 \\(\\Delta\\)，发到哪一层，和 <a href="/cs/mshr">MSHR</a> 怎么分账。不重讲强制缺失的定义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>数组 <code>a[i]</code>、矩阵行、包描述符环：缺失地址呈 \\(b, b+\\Delta, b+2\\Delta\\)。需求 load 才去 L2/DRAM 则 MLP 有，但第一条仍然付满延迟。缺口不是牺牲缓存（那是过去的受害者），而是<strong>为每条流维持一个游标，提前 \\(k\\) 块发出读</strong>。</p><p><span class="marginnote">Baer–Chen 在 TLB/表里记上一地址与步长。Jouppi 的 stream buffer 是 FIFO：预取进缓冲，CPU 命中再提升。现代核在 L1/L2 各有预取器，L2 的流更长。</span></p><p><span class="marginnote">直觉类比：步长预取像骑手摸清你的下单节奏——发现你每隔 5 分钟点一单，就提前把下一单备在路上；你真下单时货已到楼下，只差最后几十米，而不是从头等 30 分钟。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按 load PC（或页）记录上次缺失地址。若新缺失 − 上次 = \\(\\Delta\\)（块对齐），则确认步长，向 \\(addr + k\\Delta\\) 发预取，\\(k\\) 为距离。多流：多组寄存器，按 PC 分配。页边界停止或换 \\(\\Delta\\)。</p><p><span class="marginnote">数字实例：数组元素 4 字节、缓存行 64 字节，每行装 16 个元素，块距 Δ 就是 64 字节；预取距离 k=4 表示访问第 i 块时，第 i+1 到 i+4 块已在路上——k 太小遮不住延迟，太大浪费带宽。</span></p>',10)),(E(),B(o,null,{default:e(()=>[A(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20MISS%5B%22%E9%9C%80%E6%B1%82%E7%BC%BA%E5%A4%B1%22%5D%20--%3E%20STR%5B%22%E6%8C%89%20PC%20%E6%9B%B4%E6%96%B0%E6%AD%A5%E9%95%BF%22%5D%0A%20%20STR%20--%3E%20PF%5B%22%E5%90%91%20addr%2Bk%CE%94%20%E5%8F%91%E9%A2%84%E5%8F%96%22%5D%0A%20%20PF%20--%3E%20MSHR%5B%22%E5%8D%A0%E7%94%A8%20MSHR%22%5D%0A%20%20PF%20--%3E%20BUF%5B%22%E5%A1%AB%20L2%20%E6%88%96%E6%B5%81%E7%BC%93%E5%86%B2%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p>软件预取指令是同一接口的显式版：地址由编译器算，失败不得 trap。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>预取成功时，强制缺失的有效延迟下降，MLP 看起来更高。\\(\\Delta=0\\) 或随机 PC 不要训练。间接数组 <code>a[b[i]]</code> 步长在 <code>b</code> 上不在 <code>a</code> 上，简单步长器失效——那是相关预取/指针预取，本课不展开。</p><p>与 <a href="/cs/rrip-dead-block">RRIP</a>：预取填入应插成较远 RRPV，否则扫描预取变成合法的污染。下一课专讲时机与污染。</p>',4)),(E(),B(o,null,{default:e(()=>[A(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20MISS%5B%22%E9%9C%80%E6%B1%82%E7%BC%BA%E5%A4%B1%EF%BC%9Aa%5Bi%5D%20%E6%9C%AA%E4%B8%AD%22%5D%20--%3E%20LOOK%7B%22%E6%AD%A5%E9%95%BF%E8%A1%A8%EF%BC%9A%E8%AF%A5%20PC%20%E5%B7%B2%E5%AD%A6%E5%88%B0%20%CE%94%EF%BC%9F%22%7D%0A%20%20LOOK%20--%3E%7C%22%E5%B7%B2%E5%AD%A6%E5%88%B0%22%7C%20PF%5B%22%E6%8F%90%E5%89%8D%E5%90%91%20addr%20%2B%20k%CE%94%20%E5%8F%91%E9%A2%84%E5%8F%96%22%5D%0A%20%20LOOK%20--%3E%7C%22%E6%9C%AA%E5%AD%A6%E5%88%B0%22%7C%20WAIT%5B%22%E5%8F%AA%E8%AE%B0%E4%B8%8B%E5%9C%B0%E5%9D%80%EF%BC%8C%E7%AD%89%E4%B8%8B%E4%B8%80%E6%AC%A1%E7%BC%BA%E5%A4%B1%22%5D%0A%20%20WAIT%20--%3E%20CONF%5B%22%E7%9B%B8%E9%82%BB%E7%BC%BA%E5%A4%B1%E5%B7%AE%E6%81%B0%E4%B8%BA%20%CE%94%EF%BC%9A%E7%A1%AE%E8%AE%A4%E6%AD%A5%E9%95%BF%22%5D%0A%20%20CONF%20--%3E%20PF%0A%20%20PF%20--%3E%20FILL%5B%22%E9%A2%84%E5%8F%96%E5%9D%97%E8%BF%9B%20L2%20%2F%20%E6%B5%81%E7%BC%93%E5%86%B2%22%5D%0A%20%20FILL%20--%3E%20LATER%5B%22%E5%90%8E%E7%BB%AD%E9%9C%80%E6%B1%82%E5%91%BD%E4%B8%AD%EF%BC%9A%E5%85%8D%E4%BB%98%20DRAM%20%E5%BB%B6%E8%BF%9F%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<p><span class="marginnote">常见误区：以为预取「白送性能」。发早了的块可能把热行踢出小容量缓存（Jouppi 用流缓冲隔离来躲这个），发错了的块白占 MSHR 与带宽——扫描类访问还要配 RRPV 插入与反馈，不是开开关就完事。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 GPU 合并访存当步长器。也不把预取距离调参写成操作系统 API。指令预取（I-stream）类似但用取指 PC，与分支预测交互，容易在跳转后作废。</p><p>后课默认：固定 \\(\\Delta\\) 的流可以硬件预取。发早了、发错了会占带宽并踢热块，需要反馈。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>步长器按 PC 学习 \\(\\Delta\\)，流缓冲隔离预取与 L1。</li><li>预取占用与需求 miss 同一套 MSHR。</li><li>时机与污染的反馈是下一课。</li><li>出处：Jouppi, <em>ISCA</em>, 1990；Baer and Chen, <em>ISCA</em>, 1991。</li></ul>',6))])}const f=i(n,[["render",p]]);export{P as __pageData,f as default};
